fn main() {
    let mut reader = Reader::new();
    let n = reader.read() as usize;
    let mut nodes = Vec::new();
    let mut left = Vec::new();
    let mut right = Vec::new();
    for _ in 0..n {
        nodes.push(Rc::new(RefCell::new(TreeNode {
            val: reader.read(),
            left: None,
            right: None,
        })));
        left.push(reader.read());
        right.push(reader.read());
    }
    for i in 0..n {
        nodes[i].borrow_mut().left = if left[i] < 0 {
            None
        } else {
            Some(nodes[left[i] as usize].clone())
        };
        nodes[i].borrow_mut().right = if right[i] < 0 {
            None
        } else {
            Some(nodes[right[i] as usize].clone())
        };
    }
    let root = if n == 0 { None } else { Some(nodes[0].clone()) };
    emit(if Solution::is_valid_bst(root) { 1 } else { 0 });
}

